contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount == 0);
        uint balBefore = address(c).balance;
        bool reverted;
        c.sudicideAnyone(); if (__ESBMC_reverted()) return;
        assert(!reverted || (address(c).balance == balBefore));
    }
    receive() external payable {}
}

